"use client";

import { useEffect, useState, useTransition } from "react";
import { useForm, useFieldArray, useWatch } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "sonner";
import { Plus, X, Loader2, Trash2, Star, Sparkles, Search } from "lucide-react";
import type { Client, Contact } from "@prisma/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from "@/components/ui/sheet";
import {
  clientCreateSchema,
  type ClientCreateInput,
} from "@/server/clients/schemas";
import { createClient, updateClient } from "@/server/clients/actions";
import {
  cooperationStatusLabel,
  COOPERATION_STATUS_OPTIONS,
  genderLabel,
  GENDER_OPTIONS,
} from "@/lib/enums";
import {
  searchEnterpriseCandidates,
  getEnterpriseDetail,
  type EnterpriseSearchItem,
} from "@/server/yuandian/enterprise";
import { cn } from "@/lib/utils";
import { readFormPath } from "@/lib/form-path";

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingClient: (Client & { contacts?: Contact[] }) | null;
};

const emptyDefaults: ClientCreateInput = {
  name: "",
  type: "INDIVIDUAL",
  idNumber: "",
  address: "",
  legalRep: "",
  phone: "",
  email: "",
  source: "",
  cooperationStatus: "SIGNED",
  industry: "",
  gender: "",
  ethnicity: "",
  tags: [],
  notes: "",
  contacts: [
    {
      name: "",
      title: "",
      phone: "",
      email: "",
      wechat: "",
      isPrimary: true,
      notes: "",
    },
  ],
};

export function ClientSheet({ open, onOpenChange, editingClient }: Props) {
  const [isPending, startTransition] = useTransition();
  const isEdit = !!editingClient;

  const {
    register,
    control,
    handleSubmit,
    getValues,
    setValue,
    reset,
    formState: { errors },
  } = useForm<ClientCreateInput>({
    resolver: zodResolver(clientCreateSchema),
    defaultValues: emptyDefaults,
  });

  const { fields, append, remove } = useFieldArray({
    control,
    name: "contacts",
  });
  const watchedValues = useWatch({ control });
  const watch = <T = any,>(path: string) =>
    readFormPath<T>(watchedValues, path);
  const watchedType = watch<ClientCreateInput["type"]>("type");
  const watchedTags = watch<string[]>("tags");

  // Cuando cambia editing, se restablece el formulario
  useEffect(() => {
    if (!open) return;
    if (editingClient) {
      reset({
        name: editingClient.name,
        type: editingClient.type,
        idNumber: editingClient.idNumber ?? "",
        address: editingClient.address ?? "",
        legalRep: (editingClient as any).legalRep ?? "",
        phone: editingClient.phone ?? "",
        email: editingClient.email ?? "",
        source: editingClient.source ?? "",
        cooperationStatus: (editingClient as any).cooperationStatus ?? "SIGNED",
        industry: (editingClient as any).industry ?? "",
        gender: (editingClient as any).gender ?? "",
        ethnicity: (editingClient as any).ethnicity ?? "",
        tags: (editingClient.tags as string[]) ?? [],
        notes: editingClient.notes ?? "",
        contacts:
          editingClient.contacts && editingClient.contacts.length > 0
            ? editingClient.contacts.map((c) => ({
                name: c.name,
                title: c.title ?? "",
                phone: c.phone ?? "",
                email: c.email ?? "",
                wechat: c.wechat ?? "",
                isPrimary: c.isPrimary,
                notes: c.notes ?? "",
              }))
            : emptyDefaults.contacts,
      });
    } else {
      reset(emptyDefaults);
    }
  }, [editingClient, open, reset]);

  function onSubmit(values: ClientCreateInput) {
    startTransition(async () => {
      try {
        if (isEdit && editingClient) {
          await updateClient({ id: editingClient.id, ...values });
          toast.success("Cliente actualizado");
        } else {
          await createClient(values);
          toast.success("Cliente creado");
        }
        onOpenChange(false);
      } catch (err) {
        toast.error("No se pudo guardar", {
          description:
            err instanceof Error ? err.message : "Inténtelo más tarde",
        });
      }
    });
  }

  function addTag(tag: string) {
    const t = tag.trim();
    if (!t) return;
    const current = watchedTags || [];
    if (current.includes(t)) return;
    setValue("tags", [...current, t], { shouldDirty: true });
  }

  function removeTag(tag: string) {
    setValue(
      "tags",
      (watchedTags || []).filter((t) => t !== tag),
      { shouldDirty: true },
    );
  }

  // v0.27: IA para completar automáticamente el código de crédito (ruta empresa / organización)
  const [candidates, setCandidates] = useState<EnterpriseSearchItem[] | null>(
    null,
  );
  const [aiSearching, startAiSearch] = useTransition();
  const [aiFilling, startAiFill] = useTransition();

  function handleAILookup() {
    const name = (getValues("name") || "").trim();
    if (!name) {
      toast.warning(
        "Primero complete el nombre del cliente antes de usar la búsqueda con IA",
      );
      return;
    }
    startAiSearch(async () => {
      try {
        const r = await searchEnterpriseCandidates(name);
        if (!r.configured) {
          toast.error("La API de Yuandian no está configurada", {
            description:
              "Configure la API Key en Configuración → IA y Yuandian",
          });
          return;
        }
        if (r.items.length === 0) {
          toast.info("No se encontraron empresas candidatas", {
            description: "Pruebe con un nombre más completo o un apodo",
          });
          return;
        }
        setCandidates(r.items);
      } catch (err) {
        toast.error("La búsqueda falló", {
          description: err instanceof Error ? err.message : "",
        });
      }
    });
  }

  function handlePickCandidate(item: EnterpriseSearchItem) {
    startAiFill(async () => {
      setValue("idNumber", item.creditCode, {
        shouldDirty: true,
        shouldValidate: true,
      });
      setValue("name", item.name, { shouldDirty: true });
      setCandidates(null);
      try {
        const r = await getEnterpriseDetail(item.id);
        if (r.configured && r.info) {
          if (r.info.legalRep)
            setValue("legalRep", r.info.legalRep, { shouldDirty: true });
          if (r.info.address)
            setValue("address", r.info.address, { shouldDirty: true });
          toast.success(`Se completó automáticamente: ${item.name}`);
        }
      } catch (err) {
        toast.warning(
          "Error al autocompletar representante legal / dirección; puede completarlo manualmente",
          {
            description: err instanceof Error ? err.message : "",
          },
        );
      }
    });
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="flex w-full max-w-2xl flex-col gap-0 overflow-hidden p-0 sm:max-w-2xl"
      >
        <SheetHeader className="border-b border-border bg-background px-6 py-4">
          <SheetTitle className="text-lg">
            {isEdit ? "Editar cliente" : "Nuevo cliente"}
          </SheetTitle>
          <SheetDescription className="text-xs">
            Información principal del cliente + contactos; los detalles de
            contacto se mantienen por separado en contactos
          </SheetDescription>
        </SheetHeader>

        <form
          onSubmit={handleSubmit(onSubmit)}
          className="flex flex-1 flex-col overflow-hidden"
        >
          <div className="flex-1 overflow-y-auto px-6 py-5">
            {/* Información básica */}
            <Section title="Información básica">
              <Field
                label="Nombre del cliente"
                required
                error={errors.name?.message}
              >
                <Input
                  placeholder={
                    watchedType === "INDIVIDUAL"
                      ? "Juan Pérez"
                      : "Compañía XYZ S.A."
                  }
                  {...register("name")}
                />
              </Field>

              <Field label="Tipo" required>
                <Select
                  value={watchedType}
                  onValueChange={(v) =>
                    setValue("type", v as ClientCreateInput["type"], {
                      shouldDirty: true,
                    })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="INDIVIDUAL">Persona natural</SelectItem>
                    <SelectItem value="COMPANY">Empresa</SelectItem>
                    <SelectItem value="ORGANIZATION">
                      Otra organización
                    </SelectItem>
                  </SelectContent>
                </Select>
              </Field>

              <Field
                label={
                  watchedType === "INDIVIDUAL"
                    ? "Número de documento"
                    : "Código único de crédito"
                }
              >
                {watchedType === "INDIVIDUAL" ? (
                  <Input
                    className="font-mono"
                    placeholder="Número de documento con 18 dígitos"
                    {...register("idNumber")}
                  />
                ) : (
                  <div className="space-y-1">
                    <div className="flex gap-1">
                      <Input
                        className="flex-1 font-mono"
                        placeholder="Código de crédito con 18 dígitos"
                        {...register("idNumber")}
                      />
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={handleAILookup}
                        disabled={aiSearching || aiFilling}
                        className="h-9 shrink-0 gap-1"
                        title="Busca por nombre del cliente en Yuandian y rellena automáticamente el código de crédito / representante legal / dirección registrada"
                      >
                        {aiSearching ? (
                          <Loader2 className="h-3 w-3 animate-spin" />
                        ) : (
                          <Sparkles className="h-3 w-3" />
                        )}
                        Buscar con IA
                      </Button>
                    </div>
                    {candidates && candidates.length > 0 && (
                      <div className="rounded-md border border-border bg-muted/30 p-1.5">
                        <div className="mb-1 flex items-center gap-1 text-[10px] text-muted-foreground">
                          <Search className="h-3 w-3" />
                          Hay {candidates.length} opciones; haga clic para
                          completar
                        </div>
                        <ul className="space-y-1">
                          {candidates.map((c) => (
                            <li key={c.id}>
                              <button
                                type="button"
                                onClick={() => handlePickCandidate(c)}
                                disabled={aiFilling}
                                className="w-full rounded border border-border bg-background px-2 py-1.5 text-left text-xs transition-colors hover:border-input hover:bg-muted hover:text-foreground disabled:opacity-50"
                              >
                                <div className="font-medium">{c.name}</div>
                                <div className="font-mono text-[10px] text-muted-foreground">
                                  {c.creditCode}
                                </div>
                              </button>
                            </li>
                          ))}
                        </ul>
                        <button
                          type="button"
                          onClick={() => setCandidates(null)}
                          className="mt-1 w-full text-[10px] text-muted-foreground hover:text-foreground"
                        >
                          Cerrar
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </Field>

              <Field label="Teléfono principal">
                <Input
                  className="font-mono"
                  placeholder="Número de celular de 11 dígitos"
                  {...register("phone")}
                />
              </Field>

              <Field label="Correo electrónico" error={errors.email?.message}>
                <Input
                  type="email"
                  placeholder="contacto@ejemplo.com"
                  {...register("email")}
                />
              </Field>

              <Field label="Dirección">
                <Input
                  placeholder="Dirección detallada"
                  {...register("address")}
                />
              </Field>

              {watchedType !== "INDIVIDUAL" && (
                <Field label="Representante legal">
                  <Input
                    placeholder="Nombre del representante legal"
                    {...register("legalRep")}
                  />
                </Field>
              )}

              <Field label="Fuente del caso">
                <Input
                  placeholder="Persona de referencia / fuente pública / recompra de cliente"
                  {...register("source")}
                />
              </Field>

              <Field label="Estado de colaboración">
                <Select
                  value={watch("cooperationStatus")}
                  onValueChange={(v) =>
                    setValue(
                      "cooperationStatus",
                      v as ClientCreateInput["cooperationStatus"],
                      {
                        shouldDirty: true,
                      },
                    )
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {COOPERATION_STATUS_OPTIONS.map((s) => (
                      <SelectItem key={s} value={s}>
                        {cooperationStatusLabel[s]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </Field>

              <Field label="Industria">
                <Input
                  placeholder="Ej. manufactura / tecnología / inmobiliario"
                  {...register("industry")}
                />
              </Field>

              {watchedType === "INDIVIDUAL" && (
                <>
                  <Field label="Género">
                    <Select
                      value={watch("gender") || "UNSET"}
                      onValueChange={(v) =>
                        setValue(
                          "gender",
                          v === "UNSET" ? "" : (v as "MALE" | "FEMALE"),
                          { shouldDirty: true },
                        )
                      }
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Sin completar" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="UNSET">Sin completar</SelectItem>
                        {GENDER_OPTIONS.map((g) => (
                          <SelectItem key={g} value={g}>
                            {genderLabel[g]}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </Field>

                  <Field label="Etnia">
                    <Input placeholder="Ej. Han" {...register("ethnicity")} />
                  </Field>
                </>
              )}

              <Field label="Etiquetas">
                <TagInput
                  tags={watchedTags || []}
                  onAdd={addTag}
                  onRemove={removeTag}
                />
              </Field>

              <Field label="Notas" full>
                <Textarea
                  rows={3}
                  placeholder="Opcional"
                  {...register("notes")}
                />
              </Field>
            </Section>

            {/* Contactos */}
            <Section
              title="Contactos"
              action={
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    append({
                      name: "",
                      title: "",
                      phone: "",
                      email: "",
                      wechat: "",
                      isPrimary: false,
                      notes: "",
                    })
                  }
                  className="h-7 gap-1"
                >
                  <Plus className="h-3.5 w-3.5" />
                  Agregar contacto
                </Button>
              }
            >
              <div className="col-span-2 space-y-3">
                {fields.map((field, idx) => (
                  <div
                    key={field.id}
                    className="rounded-lg border border-border bg-background p-3"
                  >
                    <div className="mb-2 flex items-center justify-between">
                      <span className="text-xs font-medium text-muted-foreground">
                        Contacto {idx + 1}
                      </span>
                      <div className="flex items-center gap-2">
                        <label className="flex cursor-pointer items-center gap-1 text-xs text-muted-foreground">
                          <Checkbox
                            checked={watch(`contacts.${idx}.isPrimary`)}
                            onCheckedChange={(c) => {
                              if (c) {
                                // Opción única: cancelar otros contactos principales
                                fields.forEach((_, i) => {
                                  setValue(
                                    `contacts.${i}.isPrimary`,
                                    i === idx,
                                  );
                                });
                              } else {
                                setValue(`contacts.${idx}.isPrimary`, false);
                              }
                            }}
                          />
                          <Star className="h-3 w-3" /> Contacto principal
                        </label>
                        {fields.length > 1 && (
                          <Button
                            type="button"
                            variant="ghost"
                            size="sm"
                            onClick={() => remove(idx)}
                            className="h-7 w-7 p-0 text-destructive"
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </Button>
                        )}
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      <Field
                        label="Nombre"
                        required
                        error={errors.contacts?.[idx]?.name?.message}
                      >
                        <Input
                          placeholder="Nombre"
                          {...register(`contacts.${idx}.name`)}
                        />
                      </Field>
                      <Field label="Cargo">
                        <Input
                          placeholder="Representante legal / Gerente general / Asesor legal"
                          {...register(`contacts.${idx}.title`)}
                        />
                      </Field>
                      <Field label="Teléfono">
                        <Input
                          className="font-mono"
                          {...register(`contacts.${idx}.phone`)}
                        />
                      </Field>
                      <Field
                        label="Correo electrónico"
                        error={errors.contacts?.[idx]?.email?.message}
                      >
                        <Input
                          type="email"
                          {...register(`contacts.${idx}.email`)}
                        />
                      </Field>
                      <Field label="WeChat">
                        <Input {...register(`contacts.${idx}.wechat`)} />
                      </Field>
                      <Field label="Notas">
                        <Input {...register(`contacts.${idx}.notes`)} />
                      </Field>
                    </div>
                  </div>
                ))}
              </div>
            </Section>
          </div>

          {/* Barra inferior */}
          <SheetFooter className="border-t border-border bg-background px-6 py-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isPending}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isPending} className="gap-1.5 ">
              {isPending && <Loader2 className="h-4 w-4 animate-spin" />}
              {isEdit ? "Guardar" : "Crear cliente"}
            </Button>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  );
}

function Section({
  title,
  action,
  children,
}: {
  title: string;
  action?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <section className="mb-6">
      <header className="mb-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="h-3 w-0.5 rounded-full bg-primary" />
          <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            {title}
          </h3>
        </div>
        {action}
      </header>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">{children}</div>
    </section>
  );
}

function Field({
  label,
  required,
  full,
  error,
  children,
}: {
  label: string;
  required?: boolean;
  full?: boolean;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={cn("space-y-1.5", full && "col-span-2")}>
      <Label className="flex items-center gap-1 text-xs">
        {label}
        {required && <span className="text-destructive">*</span>}
      </Label>
      {children}
      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}

function TagInput({
  tags,
  onAdd,
  onRemove,
}: {
  tags: string[];
  onAdd: (t: string) => void;
  onRemove: (t: string) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-1.5 rounded-md border border-input bg-background px-2 py-1.5 focus-within:border-primary">
      {tags.map((t) => (
        <span
          key={t}
          className="inline-flex items-center gap-1 rounded-md bg-primary/15 px-2 py-0.5 text-xs text-primary"
        >
          {t}
          <button
            type="button"
            onClick={() => onRemove(t)}
            className="hover:text-foreground"
            aria-label={`Eliminar ${t}`}
          >
            <X className="h-3 w-3" />
          </button>
        </span>
      ))}
      <input
        type="text"
        placeholder={
          tags.length === 0
            ? "Escriba y presione Enter para agregar una etiqueta"
            : ""
        }
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            onAdd((e.target as HTMLInputElement).value);
            (e.target as HTMLInputElement).value = "";
          }
        }}
        className="flex-1 min-w-24 border-0 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
      />
    </div>
  );
}
